INSERT OR IGNORE INTO places (id, name, kind, area, summary, best_times, styles, visit_minutes, travel_minutes, distance_km, entry_fee_vnd, parking_fee_vnd, difficulty, best_months, notes, cover_image, sources_json, status, created_at, updated_at) VALUES ('pl-dinh-gio', 'Đỉnh Gió', 'viewpoint', 'Trung tâm Tà Xùa', 'Điểm cao thoáng gần trung tâm, nhìn bao quát núi và biển mây; quanh đó có nhiều quán cà phê và homestay.', '["sunrise","sunset"]', '["san-may","chup-anh","chill"]', 60, 8, 2, NULL, NULL, 'de', '[]', 'Vietnam Airlines ghi khoảng 2 km/8 phút xe máy; Tổng cục Du lịch ghi khoảng 3 km trên đường đi Xím Vàng.', NULL, '[{"name":"Vietnam Airlines — Cẩm nang du lịch Tà Xùa","url":"https://www.vietnamairlines.com/kr/vi/plan-book/travel/travel-guide/du-lich-ta-xua","accessed":"2026-11-14"},{"name":"Tổng cục Du lịch — Tà Xùa, nấc thang lên ngàn mây","url":"https://vietnam.travel/vi/node/1572","accessed":"2026-11-14"}]', 'pending', '2026-11-14T00:00:00.000Z', '2026-11-14T00:00:00.000Z');
INSERT OR IGNORE INTO places (id, name, kind, area, summary, best_times, styles, visit_minutes, travel_minutes, distance_km, entry_fee_vnd, parking_fee_vnd, difficulty, best_months, notes, cover_image, sources_json, status, created_at, updated_at) VALUES ('pl-song-lung-khung-long', 'Sống lưng khủng long (Háng Đồng)', 'trek', 'Háng Đồng', 'Dải sống núi hẹp nhìn xuống thung lũng sâu, điểm săn mây nổi tiếng nhất vùng; đường xuống dốc, nhiều đá.', '["sunrise"]', '["san-may","kham-pha","chup-anh"]', 150, 30, 13, NULL, NULL, 'kho', '[10,11,12,1,2,3,4]', 'Vietnam Airlines: khoảng 13 km/30 phút, xe ôm địa phương khoảng 50.000đ/người khứ hồi; VnExpress ghi khoảng 15 km. Ngày mây dày có thể chưa tan trước 10h (VnExpress). Không tự lái nếu tay lái chưa vững.', NULL, '[{"name":"Vietnam Airlines — Cẩm nang du lịch Tà Xùa","url":"https://www.vietnamairlines.com/kr/vi/plan-book/travel/travel-guide/du-lich-ta-xua","accessed":"2026-11-14"},{"name":"VnExpress — Cẩm nang du lịch Tà Xùa","url":"https://vnexpress.net/cam-nang-du-lich-ta-xua-4656282.html","accessed":"2026-11-14"}]', 'pending', '2026-11-14T00:00:00.000Z', '2026-11-14T00:00:00.000Z');
INSERT OR IGNORE INTO places (id, name, kind, area, summary, best_times, styles, visit_minutes, travel_minutes, distance_km, entry_fee_vnd, parking_fee_vnd, difficulty, best_months, notes, cover_image, sources_json, status, created_at, updated_at) VALUES ('pl-mom-ca-heo', 'Mỏm Cá Heo', 'viewpoint', 'Bản Bẹ', 'Phiến đá tự nhiên nhô ra vực, hình như đầu cá heo giữa tầng mây; điểm chụp ảnh nổi tiếng.', '["morning","afternoon"]', '["chup-anh","kham-pha","san-may"]', 60, 30, 15, NULL, NULL, 'trung-binh', '[]', 'Vietnam Airlines: khoảng 15 km/30 phút; Finhay ghi khoảng 10 km trên đường Tà Xùa – Háng Đồng.', NULL, '[{"name":"Vietnam Airlines — Cẩm nang du lịch Tà Xùa","url":"https://www.vietnamairlines.com/kr/vi/plan-book/travel/travel-guide/du-lich-ta-xua","accessed":"2026-11-14"},{"name":"Finhay — Top địa điểm du lịch Tà Xùa","url":"https://www.finhay.com.vn/dia-diem-du-lich-ta-xua","accessed":"2026-11-14"}]', 'pending', '2026-11-14T00:00:00.000Z', '2026-11-14T00:00:00.000Z');
INSERT OR IGNORE INTO places (id, name, kind, area, summary, best_times, styles, visit_minutes, travel_minutes, distance_km, entry_fee_vnd, parking_fee_vnd, difficulty, best_months, notes, cover_image, sources_json, status, created_at, updated_at) VALUES ('pl-cay-co-don', 'Cây cô đơn (Suối Sập)', 'viewpoint', 'Bản Bẹ', 'Cây đứng một mình trên đồi nhỏ, phía dưới là dòng Suối Sập; thường đi cùng chuyến Mỏm Cá Heo.', '["morning","afternoon"]', '["chup-anh","chill"]', 45, 35, 16, 10000, 5000, 'de', '[]', 'Phí vào 10.000đ/người, gửi xe 5.000đ/xe (Vietnam Airlines). Thời gian đi 35 phút là ước tính: cách Mỏm Cá Heo khoảng 1–1,5 km (Finhay) — admin xác nhận khi duyệt. Cùng cung đường Mỏm Cá Heo, thuộc khu thủy điện Suối Sập xã Háng Đồng (Finhay) — xếp chung khu Bản Bẹ để tính quãng đi. Về trước khi trời tối vì không có đèn đường. VnExpress nhắc tới một cây táo mèo cô đơn khác ở Đỉnh Gió, cách trung tâm hơn 1 km.', NULL, '[{"name":"Vietnam Airlines — Cẩm nang du lịch Tà Xùa","url":"https://www.vietnamairlines.com/kr/vi/plan-book/travel/travel-guide/du-lich-ta-xua","accessed":"2026-11-14"},{"name":"Finhay — Top địa điểm du lịch Tà Xùa","url":"https://www.finhay.com.vn/dia-diem-du-lich-ta-xua","accessed":"2026-11-14"},{"name":"VnExpress — Cẩm nang du lịch Tà Xùa","url":"https://vnexpress.net/cam-nang-du-lich-ta-xua-4656282.html","accessed":"2026-11-14"}]', 'pending', '2026-11-14T00:00:00.000Z', '2026-11-14T00:00:00.000Z');
INSERT OR IGNORE INTO places (id, name, kind, area, summary, best_times, styles, visit_minutes, travel_minutes, distance_km, entry_fee_vnd, parking_fee_vnd, difficulty, best_months, notes, cover_image, sources_json, status, created_at, updated_at) VALUES ('pl-thao-nguyen', 'Thảo nguyên Tà Xùa', 'nature', 'Bản Bẹ', 'Đồi cỏ thoải rộng, hợp dã ngoại, cắm trại và ngắm hoàng hôn; cùng cung đường Mỏm Cá Heo.', '["afternoon","sunset"]', '["chill","chup-anh","kham-pha"]', 90, 40, 14, 30000, NULL, 'de', '[]', 'Vietnam Airlines: khoảng 14 km/40 phút, vé 30.000đ/người; VnExpress ghi khoảng 10 km, đường rộng ít cua.', NULL, '[{"name":"Vietnam Airlines — Cẩm nang du lịch Tà Xùa","url":"https://www.vietnamairlines.com/kr/vi/plan-book/travel/travel-guide/du-lich-ta-xua","accessed":"2026-11-14"},{"name":"VnExpress — Cẩm nang du lịch Tà Xùa","url":"https://vnexpress.net/cam-nang-du-lich-ta-xua-4656282.html","accessed":"2026-11-14"}]', 'pending', '2026-11-14T00:00:00.000Z', '2026-11-14T00:00:00.000Z');
INSERT OR IGNORE INTO places (id, name, kind, area, summary, best_times, styles, visit_minutes, travel_minutes, distance_km, entry_fee_vnd, parking_fee_vnd, difficulty, best_months, notes, cover_image, sources_json, status, created_at, updated_at) VALUES ('pl-mam-xoi-xim-vang', 'Mâm xôi Xím Vàng', 'nature', 'Xím Vàng', 'Ruộng bậc thang hình vòng cung giữa thung lũng, đẹp nhất mùa lúa chín.', '["morning","afternoon"]', '["chup-anh","kham-pha"]', 60, 40, 20, NULL, NULL, 'de', '[9,10]', 'Vietnam Airlines: khoảng 20 km/40 phút, đường lớn dễ đi; lúa chín tháng 9–10.', NULL, '[{"name":"Vietnam Airlines — Cẩm nang du lịch Tà Xùa","url":"https://www.vietnamairlines.com/kr/vi/plan-book/travel/travel-guide/du-lich-ta-xua","accessed":"2026-11-14"}]', 'pending', '2026-11-14T00:00:00.000Z', '2026-11-14T00:00:00.000Z');
INSERT OR IGNORE INTO places (id, name, kind, area, summary, best_times, styles, visit_minutes, travel_minutes, distance_km, entry_fee_vnd, parking_fee_vnd, difficulty, best_months, notes, cover_image, sources_json, status, created_at, updated_at) VALUES ('pl-doi-che-shan-tuyet', 'Rừng chè Shan tuyết cổ thụ (bản Bẹ)', 'village', 'Bản Bẹ', 'Vùng chè Shan tuyết cổ thụ của người Mông; có thể xem hái, sao chè và thưởng trà.', '["morning","afternoon"]', '["kham-pha","chill"]', 90, NULL, 7, NULL, NULL, 'trung-binh', '[]', 'VnEconomy: bản Bẹ cách trung tâm xã khoảng 7 km, nhiều cây chè cổ thụ nhất xã. Chưa có nguồn về thời gian đi nên chỉ hiện ở mục gợi ý thêm.', NULL, '[{"name":"VnEconomy — Ngẩn ngơ giữa rừng chè cổ thụ Tà Xùa","url":"https://vneconomy.vn/ngan-ngo-giua-rung-che-co-thu-ta-xua.htm","accessed":"2026-11-14"}]', 'pending', '2026-11-14T00:00:00.000Z', '2026-11-14T00:00:00.000Z');
INSERT OR IGNORE INTO places (id, name, kind, area, summary, best_times, styles, visit_minutes, travel_minutes, distance_km, entry_fee_vnd, parking_fee_vnd, difficulty, best_months, notes, cover_image, sources_json, status, created_at, updated_at) VALUES ('pl-khe-cai', 'Khe Cải', 'viewpoint', 'Khe Cải', 'Khoảng đồi rộng ngắm bình minh, hoàng hôn và cắm trại; không quá xa trung tâm.', '["sunrise","sunset"]', '["san-may","chill","chup-anh"]', 60, NULL, NULL, NULL, NULL, 'de', '[]', 'Xanh SM mô tả đường đi khá dễ, không xa trung tâm nhưng không ghi số km/phút.', NULL, '[{"name":"Xanh SM — Cẩm nang Tà Xùa","url":"https://www.greensm.com/vn-vi/news/ta-xua","accessed":"2026-11-14"}]', 'pending', '2026-11-14T00:00:00.000Z', '2026-11-14T00:00:00.000Z');
